"""Execute original v0.4 indicator SQL without changing indicator definitions."""
import csv,json,os,sqlite3,sys
from pathlib import Path

SQL_LAST_TILE = "WITH RECURSIVE\r\nparams(season_year, stage) AS (VALUES (NULL, NULL)),\r\n/* selected seasons/stages: all tsumo wins */\r\ntsumo AS (\r\n  SELECT e.id agari_event_id,e.kyoku_id,e.event_order agari_order,ae.actor_player_id,\r\n         CASE ae.agari_tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE ae.agari_tile END agari_tile,\r\n         (SELECT MAX(ed.event_order) FROM event ed JOIN draw_event d ON d.event_id=ed.id\r\n          WHERE ed.kyoku_id=e.kyoku_id AND d.actor_player_id=ae.actor_player_id AND ed.event_order<e.event_order) win_draw_order\r\n  FROM event e JOIN agari_event ae ON ae.event_id=e.id JOIN kyoku k ON k.id=e.kyoku_id JOIN game g ON g.id=k.game_id\r\n  JOIN season_stage ss ON ss.id=g.season_stage_id\r\n  JOIN league_season ls ON ls.id=ss.league_season_id\r\n  CROSS JOIN params prm\r\n  WHERE (prm.season_year IS NULL OR ls.start_year=prm.season_year)\r\n    AND (prm.stage IS NULL OR ss.stage=prm.stage)\r\n    AND e.type='tsumo' AND ae.target_player_id IS NULL\r\n),\r\n/* latest stored concealed hand before the winning draw */\r\nbase AS (\r\n  SELECT t.*,\r\n         (SELECT MAX(es.event_order) FROM event es JOIN player_state ps ON ps.event_id=es.id AND ps.player_id=t.actor_player_id\r\n          WHERE es.kyoku_id=t.kyoku_id AND es.event_order<t.win_draw_order) state_order\r\n  FROM tsumo t\r\n),\r\nbh AS (\r\n  SELECT b.*,ps.hand\r\n  FROM base b JOIN event es ON es.kyoku_id=b.kyoku_id AND es.event_order=b.state_order\r\n  JOIN player_state ps ON ps.event_id=es.id AND ps.player_id=b.actor_player_id\r\n  WHERE EXISTS (\r\n    SELECT 1 FROM event ek\r\n    LEFT JOIN ankan_event ak ON ak.event_id=ek.id AND ak.actor_player_id=b.actor_player_id\r\n    LEFT JOIN shominkan_event sk ON sk.event_id=ek.id AND sk.actor_player_id=b.actor_player_id\r\n    LEFT JOIN daiminkan_event dk ON dk.event_id=ek.id AND dk.actor_player_id=b.actor_player_id\r\n    WHERE ek.kyoku_id=b.kyoku_id AND ek.event_order>b.state_order AND ek.event_order<b.win_draw_order\r\n      AND (ak.event_id IS NOT NULL OR sk.event_id IS NOT NULL OR dk.event_id IS NOT NULL)\r\n  )\r\n),\r\nsplit(caseid,rest,tile) AS (\r\n  SELECT agari_event_id,hand||',','' FROM bh\r\n  UNION ALL\r\n  SELECT caseid,substr(rest,instr(rest,',')+1),substr(rest,1,instr(rest,',')-1) FROM split WHERE rest<>''\r\n),\r\nbase_tiles AS (\r\n  SELECT caseid,CASE tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE tile END tile,COUNT(*) cnt\r\n  FROM split WHERE tile<>'' GROUP BY caseid,2\r\n),\r\n/* changes to this player's concealed hand after saved state, excluding the winning draw */\r\ndelta_raw AS (\r\n  SELECT b.agari_event_id caseid,CASE d.tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE d.tile END tile,1 delta\r\n  FROM bh b JOIN event e ON e.kyoku_id=b.kyoku_id JOIN draw_event d ON d.event_id=e.id AND d.actor_player_id=b.actor_player_id\r\n  WHERE e.event_order>b.state_order AND e.event_order<b.win_draw_order\r\n  UNION ALL\r\n  SELECT b.agari_event_id,CASE d.tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE d.tile END,-1\r\n  FROM bh b JOIN event e ON e.kyoku_id=b.kyoku_id JOIN discard_event d ON d.event_id=e.id AND d.actor_player_id=b.actor_player_id\r\n  WHERE e.event_order>b.state_order AND e.event_order<b.win_draw_order\r\n  UNION ALL\r\n  SELECT b.agari_event_id,CASE a.tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE a.tile END,-4\r\n  FROM bh b JOIN event e ON e.kyoku_id=b.kyoku_id JOIN ankan_event a ON a.event_id=e.id AND a.actor_player_id=b.actor_player_id\r\n  WHERE e.event_order>b.state_order AND e.event_order<b.win_draw_order\r\n  UNION ALL\r\n  SELECT b.agari_event_id,CASE a.tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE a.tile END,-1\r\n  FROM bh b JOIN event e ON e.kyoku_id=b.kyoku_id JOIN shominkan_event a ON a.event_id=e.id AND a.actor_player_id=b.actor_player_id\r\n  WHERE e.event_order>b.state_order AND e.event_order<b.win_draw_order\r\n  UNION ALL\r\n  SELECT b.agari_event_id,CASE a.tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE a.tile END,-3\r\n  FROM bh b JOIN event e ON e.kyoku_id=b.kyoku_id JOIN daiminkan_event a ON a.event_id=e.id AND a.actor_player_id=b.actor_player_id\r\n  WHERE e.event_order>b.state_order AND e.event_order<b.win_draw_order\r\n),\r\ndelta AS (SELECT caseid,tile,SUM(delta) delta FROM delta_raw GROUP BY caseid,tile),\r\ntiles(i,tile) AS (VALUES\r\n (0,'1m'),(1,'2m'),(2,'3m'),(3,'4m'),(4,'5m'),(5,'6m'),(6,'7m'),(7,'8m'),(8,'9m'),\r\n (9,'1p'),(10,'2p'),(11,'3p'),(12,'4p'),(13,'5p'),(14,'6p'),(15,'7p'),(16,'8p'),(17,'9p'),\r\n (18,'1s'),(19,'2s'),(20,'3s'),(21,'4s'),(22,'5s'),(23,'6s'),(24,'7s'),(25,'8s'),(26,'9s'),\r\n (27,'1z'),(28,'2z'),(29,'3z'),(30,'4z'),(31,'5z'),(32,'6z'),(33,'7z')),\r\nhandcnt AS (\r\n  SELECT b.agari_event_id caseid,t.i,t.tile,COALESCE(bt.cnt,0)+COALESCE(d.delta,0) cnt\r\n  FROM bh b CROSS JOIN tiles t LEFT JOIN base_tiles bt ON bt.caseid=b.agari_event_id AND bt.tile=t.tile\r\n  LEFT JOIN delta d ON d.caseid=b.agari_event_id AND d.tile=t.tile\r\n),\r\n/* Try every tile as the next tile, then every possible pair; recursively strip melds. */\r\nseed AS (\r\n  SELECT h.caseid,w.i wait_i,w.tile wait_tile,p.i pair_i,\r\n         json_set((SELECT json_group_object(CAST(i AS TEXT),cnt+CASE WHEN i=w.i THEN 1 ELSE 0 END) FROM handcnt x WHERE x.caseid=h.caseid),\r\n                  '$.\"'||p.i||'\"',\r\n                  (SELECT cnt+CASE WHEN i=w.i THEN 1 ELSE 0 END FROM handcnt x WHERE x.caseid=h.caseid AND x.i=p.i)-2) js\r\n  FROM (SELECT DISTINCT caseid FROM handcnt) h CROSS JOIN tiles w CROSS JOIN tiles p\r\n  WHERE (SELECT cnt+CASE WHEN i=w.i THEN 1 ELSE 0 END FROM handcnt x WHERE x.caseid=h.caseid AND x.i=p.i)>=2\r\n    AND (SELECT SUM(cnt) FROM handcnt x WHERE x.caseid=h.caseid)+1 IN (2,5,8,11,14)\r\n),\r\nmeld(caseid,wait_i,wait_tile,pair_i,js) AS (\r\n  SELECT caseid,wait_i,wait_tile,pair_i,js FROM seed\r\n  UNION ALL\r\n  SELECT m.caseid,m.wait_i,m.wait_tile,m.pair_i,\r\n         json_set(m.js,'$.\"'||f.i||'\"',json_extract(m.js,'$.\"'||f.i||'\"')-3)\r\n  FROM meld m JOIN tiles f ON f.i=(SELECT MIN(t.i) FROM tiles t WHERE COALESCE(json_extract(m.js,'$.\"'||t.i||'\"'),0)>0)\r\n  WHERE json_extract(m.js,'$.\"'||f.i||'\"')>=3\r\n  UNION ALL\r\n  SELECT m.caseid,m.wait_i,m.wait_tile,m.pair_i,\r\n         json_set(json_set(json_set(m.js,'$.\"'||f.i||'\"',json_extract(m.js,'$.\"'||f.i||'\"')-1),\r\n                           '$.\"'||(f.i+1)||'\"',json_extract(m.js,'$.\"'||(f.i+1)||'\"')-1),\r\n                           '$.\"'||(f.i+2)||'\"',json_extract(m.js,'$.\"'||(f.i+2)||'\"')-1)\r\n  FROM meld m JOIN tiles f ON f.i=(SELECT MIN(t.i) FROM tiles t WHERE COALESCE(json_extract(m.js,'$.\"'||t.i||'\"'),0)>0)\r\n  WHERE f.i<27 AND (f.i%9)<=6 AND json_extract(m.js,'$.\"'||(f.i+1)||'\"')>0 AND json_extract(m.js,'$.\"'||(f.i+2)||'\"')>0\r\n),\r\nstandard_wait AS (\r\n SELECT DISTINCT caseid,wait_i,wait_tile FROM meld m\r\n WHERE NOT EXISTS (SELECT 1 FROM tiles t WHERE COALESCE(json_extract(m.js,'$.\"'||t.i||'\"'),0)>0)\r\n),\r\ncandidate_counts AS (\r\n SELECT h.caseid,w.i wait_i,w.tile wait_tile,h.i,h.cnt+CASE WHEN h.i=w.i THEN 1 ELSE 0 END cnt\r\n FROM handcnt h CROSS JOIN tiles w\r\n),\r\nchiitoi_wait AS (\r\n SELECT caseid,wait_i,MAX(wait_tile) wait_tile FROM candidate_counts GROUP BY caseid,wait_i\r\n HAVING SUM(cnt)=14 AND SUM(CASE WHEN cnt=2 THEN 1 ELSE 0 END)=7 AND SUM(CASE WHEN cnt NOT IN(0,2) THEN 1 ELSE 0 END)=0\r\n),\r\nkokushi_wait AS (\r\n SELECT caseid,wait_i,MAX(wait_tile) wait_tile FROM candidate_counts\r\n WHERE i IN(0,8,9,17,18,26,27,28,29,30,31,32,33)\r\n GROUP BY caseid,wait_i\r\n HAVING SUM(cnt)=14 AND SUM(CASE WHEN cnt>=1 THEN 1 ELSE 0 END)=13 AND SUM(CASE WHEN cnt>=2 THEN 1 ELSE 0 END)=1\r\n),\r\nkan_waits AS (SELECT * FROM standard_wait UNION SELECT * FROM chiitoi_wait UNION SELECT * FROM kokushi_wait),\r\nnormal_source AS (\r\n SELECT b.agari_event_id,pts.waiting_tiles\r\n FROM base b JOIN event es ON es.kyoku_id=b.kyoku_id AND es.event_order=b.state_order\r\n JOIN player_tenpai_state pts ON pts.event_id=es.id AND pts.player_id=b.actor_player_id\r\n WHERE NOT EXISTS (SELECT 1 FROM bh x WHERE x.agari_event_id=b.agari_event_id)\r\n),\r\nwsplit(caseid,rest,tile) AS (\r\n SELECT agari_event_id,waiting_tiles||',','' FROM normal_source\r\n UNION ALL SELECT caseid,substr(rest,instr(rest,',')+1),substr(rest,1,instr(rest,',')-1) FROM wsplit WHERE rest<>''\r\n),\r\nnormal_waits AS (\r\n SELECT caseid,-1 wait_i,CASE tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE tile END wait_tile\r\n FROM wsplit WHERE tile<>''\r\n),\r\nwaits AS (SELECT * FROM normal_waits UNION SELECT * FROM kan_waits),\r\n/* Tiles definitely not in the live wall immediately before the winning draw: all four initial hands, all earlier draws, revealed dora indicators. */\r\nknown_raw AS (\r\n SELECT t.agari_event_id,CASE j.value WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE j.value END tile\r\n FROM tsumo t JOIN event e ON e.kyoku_id=t.kyoku_id JOIN haipai_event h ON h.event_id=e.id\r\n JOIN json_each('[\"'||replace(h.hand,',','\",\"')||'\"]') j WHERE e.event_order<t.win_draw_order\r\n UNION ALL\r\n SELECT t.agari_event_id,CASE d.tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE d.tile END\r\n FROM tsumo t JOIN event e ON e.kyoku_id=t.kyoku_id JOIN draw_event d ON d.event_id=e.id WHERE e.event_order<t.win_draw_order\r\n UNION ALL\r\n SELECT t.agari_event_id,CASE di.dora_indicator_tile WHEN '0m' THEN '5m' WHEN '0p' THEN '5p' WHEN '0s' THEN '5s' ELSE di.dora_indicator_tile END\r\n FROM tsumo t JOIN event e ON e.kyoku_id=t.kyoku_id JOIN dora_indicator_event di ON di.event_id=e.id WHERE e.event_order<t.win_draw_order\r\n),\r\nknown AS (SELECT agari_event_id,tile,COUNT(*) known_count FROM known_raw GROUP BY agari_event_id,tile),\r\njudgement AS (\r\n SELECT w.caseid agari_event_id,\r\n        GROUP_CONCAT(w.wait_tile||'='||(4-COALESCE(k.known_count,0)),', ') wait_detail,\r\n        SUM(4-COALESCE(k.known_count,0)) total_remaining,\r\n        CASE WHEN SUM(4-COALESCE(k.known_count,0))=1 THEN 1 ELSE 0 END confirmed_last_tile\r\n FROM waits w LEFT JOIN known k ON k.agari_event_id=w.caseid AND k.tile=w.wait_tile GROUP BY w.caseid\r\n),\r\ndetail AS (\r\n SELECT t.agari_event_id,t.actor_player_id,p.name player_name,g.date,g.day_game_number,k.id kyoku_id,k.round,k.honba_count,\r\n        t.agari_tile,j.wait_detail,j.total_remaining,j.confirmed_last_tile\r\n FROM tsumo t JOIN judgement j ON j.agari_event_id=t.agari_event_id JOIN player p ON p.id=t.actor_player_id\r\n JOIN kyoku k ON k.id=t.kyoku_id JOIN game g ON g.id=k.game_id\r\n)\r\nSELECT player_name,COUNT(*) tsumo_agari_count,SUM(confirmed_last_tile) confirmed_last_tile_tsumo_count,\r\n       ROUND(100.0*SUM(confirmed_last_tile)/COUNT(*),2) confirmed_last_tile_tsumo_rate\r\nFROM detail GROUP BY actor_player_id,player_name\r\nORDER BY confirmed_last_tile_tsumo_rate DESC,confirmed_last_tile_tsumo_count DESC,player_name"
SQL_KYOTAKU = "WITH\r\nparams AS (SELECT NULL AS player_id, NULL AS start_year, NULL AS stage),\r\nselected_games AS (\r\n SELECT g.id AS game_id\r\n FROM game g JOIN season_stage ss ON ss.id=g.season_stage_id\r\n JOIN league_season ls ON ls.id=ss.league_season_id CROSS JOIN params p\r\n WHERE (p.start_year IS NULL OR ls.start_year=p.start_year)\r\n   AND (p.stage IS NULL OR ss.stage=p.stage)\r\n),\r\nparticipants AS (\r\n SELECT gr.game_id,gr.player_id,gr.rank\r\n FROM game_player_result gr JOIN selected_games sg ON sg.game_id=gr.game_id\r\n),\r\nreach_spent AS (\r\n SELECT e.kyoku_id,r.actor_player_id AS player_id,COUNT(*) AS sticks\r\n FROM reach_event r JOIN event e ON e.id=r.event_id\r\n JOIN kyoku k ON k.id=e.kyoku_id JOIN selected_games sg ON sg.game_id=k.game_id\r\n WHERE r.is_accepted=1\r\n GROUP BY e.kyoku_id,r.actor_player_id\r\n),\r\nwin_received AS (\r\n SELECT e.kyoku_id,a.actor_player_id AS player_id,SUM(a.kyotaku_points) AS points\r\n FROM agari_event a JOIN event e ON e.id=a.event_id\r\n JOIN kyoku k ON k.id=e.kyoku_id JOIN selected_games sg ON sg.game_id=k.game_id\r\n GROUP BY e.kyoku_id,a.actor_player_id\r\n),\r\nlast_kyoku AS (\r\n SELECT k.game_id,MAX(k.id) AS kyoku_id\r\n FROM kyoku k JOIN selected_games sg ON sg.game_id=k.game_id GROUP BY k.game_id\r\n),\r\nfinal_reach AS (\r\n SELECT l.game_id,COALESCE(SUM(rs.sticks),0) AS sticks\r\n FROM last_kyoku l LEFT JOIN reach_spent rs ON rs.kyoku_id=l.kyoku_id GROUP BY l.game_id\r\n),\r\nfinal_win AS (\r\n SELECT l.game_id,COALESCE(SUM(w.points),0) AS points\r\n FROM last_kyoku l LEFT JOIN win_received w ON w.kyoku_id=l.kyoku_id GROUP BY l.game_id\r\n),\r\nfinal_balance AS (\r\n SELECT l.game_id,\r\n (k.kyotaku_count*1000 + fr.sticks*1000-fw.points) AS remaining_points\r\n FROM last_kyoku l JOIN kyoku k ON k.id=l.kyoku_id\r\n JOIN final_reach fr ON fr.game_id=l.game_id JOIN final_win fw ON fw.game_id=l.game_id\r\n),\r\nplayer_reach AS (\r\n SELECT k.game_id,rs.player_id,SUM(rs.sticks)*1000 AS spent_points, SUM(rs.sticks) AS reach_count\r\n FROM reach_spent rs JOIN kyoku k ON k.id=rs.kyoku_id GROUP BY k.game_id,rs.player_id\r\n),\r\nplayer_win AS (\r\n SELECT k.game_id,w.player_id,SUM(w.points) AS won_points\r\n FROM win_received w JOIN kyoku k ON k.id=w.kyoku_id GROUP BY k.game_id,w.player_id\r\n),\r\nper_game AS (\r\n SELECT p.game_id,p.player_id,\r\n COALESCE(pr.spent_points,0) AS reach_spent_points,\r\n COALESCE(pr.reach_count,0) AS accepted_reach_count,\r\n COALESCE(pw.won_points,0) AS agari_received_points,\r\n CASE WHEN p.rank=1 THEN fb.remaining_points ELSE 0 END AS end_received_points\r\n FROM participants p\r\n JOIN final_balance fb ON fb.game_id=p.game_id\r\n LEFT JOIN player_reach pr ON pr.game_id=p.game_id AND pr.player_id=p.player_id\r\n LEFT JOIN player_win pw ON pw.game_id=p.game_id AND pw.player_id=p.player_id\r\n)\r\nSELECT p.id AS player_id,p.name AS player_name,\r\n COUNT(*) AS games,\r\n SUM(pg.accepted_reach_count) AS accepted_reach_count,\r\n SUM(pg.reach_spent_points) AS reach_spent_points,\r\n SUM(pg.agari_received_points) AS agari_received_points,\r\n SUM(pg.end_received_points) AS end_received_points,\r\n SUM(pg.agari_received_points+pg.end_received_points-pg.reach_spent_points) AS kyotaku_net_points\r\nFROM per_game pg JOIN player p ON p.id=pg.player_id CROSS JOIN params cfg\r\nWHERE cfg.player_id IS NULL OR p.id=cfg.player_id\r\nGROUP BY p.id,p.name\r\nORDER BY kyotaku_net_points DESC,p.name"

con=sqlite3.connect("file:"+os.path.abspath(sys.argv[1])+"?mode=ro",uri=True)
con.row_factory=sqlite3.Row
out=Path("results");out.mkdir(exist_ok=True)

def run(sql,name,sort_key,reverse=True):
    rows=[dict(x) for x in con.execute(sql).fetchall()]
    print(name,"players",len(rows),flush=True)
    if not rows: raise RuntimeError("No results for "+name)
    with (out/(name+"_all.csv")).open("w",newline="",encoding="utf-8-sig") as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    ranked=sorted(rows,key=lambda r:(-r[sort_key] if reverse else r[sort_key],r["player_name"]))
    (out/(name+"_top10.json")).write_text(json.dumps(ranked[:10],ensure_ascii=False,indent=2),encoding="utf-8")
    print(name,"TOP10",json.dumps(ranked[:10],ensure_ascii=False),flush=True)
    return rows

last=run(SQL_LAST_TILE,"last_tile_tsumo","confirmed_last_tile_tsumo_rate")
kyotaku=run(SQL_KYOTAKU,"kyotaku_net","kyotaku_net_points")
net=sum(x["kyotaku_net_points"] for x in kyotaku)
print("Kyotaku zero sum:",net,flush=True)
if net!=0: raise RuntimeError("Kyotaku zero-sum validation failed: "+str(net))
bottom=sorted(kyotaku,key=lambda r:(r["kyotaku_net_points"],r["player_name"]))[:10]
(out/"kyotaku_net_bottom10.json").write_text(json.dumps(bottom,ensure_ascii=False,indent=2),encoding="utf-8")
print("KYOTAKU BOTTOM10",json.dumps(bottom,ensure_ascii=False),flush=True)
